import numpy as np
from PIL import Image
from scipy import ndimage
import json

def load(path):
    im = Image.open(path).convert('RGB')
    return np.asarray(im).astype(np.int16)

def color_mask(arr, targets, tol=70):
    m = np.zeros(arr.shape[:2], bool)
    for t in targets:
        d = np.sqrt(((arr - np.array(t, dtype=np.int16))**2).sum(-1))
        m |= d < tol
    return m

def peak_centers(mask, radius=6, thresh=0.5, min_dist=5, box=None, min_pixels=4):
    if box is not None:
        x0, y0, x1, y1 = box
        m = np.zeros_like(mask)
        m[y0:y1, x0:x1] = mask[y0:y1, x0:x1]
    else:
        m = mask
    density = ndimage.uniform_filter(m.astype(np.float64), size=2*radius+1)
    # local maxima with wide window
    k = 2*radius+1
    mx = ndimage.maximum_filter(density, size=k)
    cand = (density == mx) & (density > thresh)
    ys, xs = np.where(cand)
    order = np.argsort(-density[ys, xs])
    kept = []
    for i in order:
        y, x = ys[i], xs[i]
        ok = True
        for (ky, kx) in kept:
            if (ky-y)**2 + (kx-x)**2 < min_dist*min_dist:
                ok = False
                break
        if ok:
            kept.append((y, x))
    centers = []
    for (y, x) in kept:
        yy, xx = np.where(m)
        sel = (yy-y)**2 + (xx-x)**2 <= radius*radius
        if sel.sum() < min_pixels:
            continue
        centers.append((float(xx[sel].mean()), float(yy[sel].mean())))
    centers.sort(key=lambda c: c[0])
    return centers

def to_data(cx, cy, xt, yt, xlog=False, ylog=False):
    def conv(p, ticks, log):
        (px1, v1), (px2, v2) = ticks
        if log:
            lv = p - px1
            val = v1 * (v2/v1) ** (lv / (px2 - px1))
        else:
            val = v1 + (v2 - v1) * (p - px1) / (px2 - px1)
        return val
    return conv(cx, xt, xlog), conv(cy, yt, ylog)

def save_overlay(path, arr, points, color=(255,0,0), r=8):
    im = Image.open(path).convert('RGB')
    from PIL import ImageDraw
    dr = ImageDraw.Draw(im)
    for (x, y) in points:
        dr.ellipse([x-r, y-r, x+r, y+r], outline=color, width=2)
    im.save(path)
